window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-20891\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθεῖσε</h1><div class=\"entry-meta\"><span>DGP · ordem 106 na letra κ · nº geral 20891</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3a sing. aor. at. de καθίζω.</p></section></article>\n<article id=\"entry-dgp-20892\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθεκτέον</h1><div class=\"entry-meta\"><span>DGP · ordem 107 na letra κ · nº geral 20892</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de κατέχω.</p></section></article>\n<article id=\"entry-dgp-20893\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθεκτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 108 na letra κ · nº geral 20893</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que se pode deter ou conter: ἐν τῷ καθεκτῷ εἶναι filóstr. conter-se. 〈κατέχω〉</p></section></article>\n<article id=\"entry-dgp-20894\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθελίσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 109 na letra κ · nº geral 20894</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(3ª pl. m.-q.-perf. pas. jôn. κατειλίχατο) envolver; enrolar; enfaixar (múmia).</p></section></article>\n<article id=\"entry-dgp-20895\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθελκύω</h1><div class=\"entry-meta\"><span>DGP · ordem 110 na letra κ · nº geral 20895</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. καθελκύσω, aor. καθείλκυσα, perf. καθείλκυκα, m.-q.-perf. καθειλκύκειν; pas. aor. καθειλκύσθην, perf. καθείλκυσμαι) 1 puxar de cima para baixo; fazer descer; baixar 2 puxar para o mar (navio).</p></section></article>\n<article id=\"entry-dgp-20896\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθέλκω</h1><div class=\"entry-meta\"><span>DGP · ordem 111 na letra κ · nº geral 20896</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só impf. καθεῖλκον e fut. καθέλξω) = κα­θελκύω.</p></section></article>\n<article id=\"entry-dgp-20897\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθελών</h1><div class=\"entry-meta\"><span>DGP · ordem 112 na letra κ · nº geral 20897</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor.2 de καταιρέω.</p></section></article>\n<article id=\"entry-dgp-20898\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάθεμεν</h1><div class=\"entry-meta\"><span>DGP · ordem 113 na letra κ · nº geral 20898</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1ª pl. aor.2 de καθίημι.</p></section></article>\n<article id=\"entry-dgp-20899\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθεξῆς</h1><div class=\"entry-meta\"><span>DGP · ordem 114 na letra κ · nº geral 20899</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv., tard. 1 em seqüência; em ordem; um após o outro 2 em seguida; depois. 〈κατά, ἑξῆς〉</p></section></article>\n<article id=\"entry-dgp-20900\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάθεξις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 115 na letra κ · nº geral 20900</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 manutenção; conservação 2 interceptação; detenção; repressão. 〈κατέχω〉</p></section></article>\n<article id=\"entry-dgp-20901\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθέξω</h1><div class=\"entry-meta\"><span>DGP · ordem 116 na letra κ · nº geral 20901</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de κατέχω.</p></section></article>\n<article id=\"entry-dgp-20902\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθερπύζω</h1><div class=\"entry-meta\"><span>DGP · ordem 117 na letra κ · nº geral 20902</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só aor. καθείρπυσα, imper. καθέρπυσον) 1 escorregar; deslizar 2 descer escorregando 3 ir.</p></section></article>\n<article id=\"entry-dgp-20903\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθέρπω</h1><div class=\"entry-meta\"><span>DGP · ordem 118 na letra κ · nº geral 20903</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só impf. καθεῖρπον) = καθερπύζω. 〈κατά, ἕρπω〉</p></section></article>\n<article id=\"entry-dgp-20904\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθέστακα, καθέστηκα</h1><div class=\"entry-meta\"><span>DGP · ordem 119 na letra κ · nº geral 20904</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. καθίστημι.</p></section></article>\n<article id=\"entry-dgp-20905\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθεστηκῶς, υῖα, ός</h1><div class=\"entry-meta\"><span>DGP · ordem 120 na letra κ · nº geral 20905</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. perf. de καθίστημι.</p></section></article>\n<article id=\"entry-dgp-20906\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθεστήξω</h1><div class=\"entry-meta\"><span>DGP · ordem 121 na letra κ · nº geral 20906</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. καθίστημι.</p></section></article>\n<article id=\"entry-dgp-20907\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθεστώς, ῶσα, ός</h1><div class=\"entry-meta\"><span>DGP · ordem 122 na letra κ · nº geral 20907</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. perf. de κατίσθημι.</p></section></article>\n<article id=\"entry-dgp-20908\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθέσωσι</h1><div class=\"entry-meta\"><span>DGP · ordem 123 na letra κ · nº geral 20908</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. subj. aor. de καθέζω.</p></section></article>\n<article id=\"entry-dgp-20909\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάθετον</h1><div class=\"entry-meta\"><span>DGP · ordem 124 na letra κ · nº geral 20909</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dual aor.2 de καθίημι.</p></section></article>\n<article id=\"entry-dgp-20910\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάθετος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 125 na letra κ · nº geral 20910</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que desce a prumo; perpendicular: κατὰ κάθετον plut. em linha vertical em relação a, gen. ♦ ἡ [γραμμή] κάθετος 2 fio de prumo 3 Matem. linha perpendicular: πρός (τὴν) κάθετον μετρεῖν plut. medir perpendicularmente, verticalmente. 〈καθίημι〉</p></section></article>\n<article id=\"entry-dgp-20911\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθεύδω</h1><div class=\"entry-meta\"><span>DGP · ordem 126 na letra κ · nº geral 20911</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. át. καθηῦδον ou ἐκάθευδον, fut. καθευ­δήσω) 1 deitar-se para dormir; repousar; dormir 2 bíbl. (morto) jazer 3 ser ou permanecer inativo; estar adormecido; dormir: καθεύδουσι τὸν βίον plat. passam a vida dormindo, τοὺς νόμους δεῖ σήμερον ἐᾶν καθ. plut. é preciso hoje deixar as leis dormirem, ἐλπίδες δ’ οὔπω καθεύδουσι eur. as esperanças ainda não dormem. 〈κατά, εὕδω〉</p></section></article>\n<article id=\"entry-dgp-20912\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθευρίσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 127 na letra κ · nº geral 20912</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 descobrir; encontrar ♦ pas. 2 ser surpreendido; ser flagrado: καθευρέθη τάφον κοσμοῦσα sóf. foi surpreendida preparando a sepultura.</p></section></article>\n<article id=\"entry-dgp-20913\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθεψέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 128 na letra κ · nº geral 20913</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">καθέψω.</p></section></article>\n<article id=\"entry-dgp-20914\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθεψιάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 129 na letra κ · nº geral 20914</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(3ª pl. pres. ép. καθεψιόωνται) zombar de, gen.</p></section></article>\n<article id=\"entry-dgp-20915\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθέψω</h1><div class=\"entry-meta\"><span>DGP · ordem 130 na letra κ · nº geral 20915</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. καθεψήσω, aor. καθήψησα, m.-q.-perf. καθήψημαι; aor. pas. καθηψήθην) 1 cozer bem; tornar macio 2 acalmar 3 ferver bastante; secar 4 digerir. 〈κατά, ἕψω〉</p></section></article>\n<article id=\"entry-dgp-20916\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κἄθεον, κἀθέων</h1><div class=\"entry-meta\"><span>DGP · ordem 131 na letra κ · nº geral 20916</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase poét. de καὶ ἄθεον, καὶ ἀθέων.</p></section></article>\n<article id=\"entry-dgp-20917\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθεώρων, ας, α</h1><div class=\"entry-meta\"><span>DGP · ordem 132 na letra κ · nº geral 20917</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impf. de καθοράω.</p></section></article>\n<article id=\"entry-dgp-20918\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κἀθέως</h1><div class=\"entry-meta\"><span>DGP · ordem 133 na letra κ · nº geral 20918</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase poét. de καὶ ἀθέως.</p></section></article>\n<article id=\"entry-dgp-20919\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάθῃ</h1><div class=\"entry-meta\"><span>DGP · ordem 134 na letra κ · nº geral 20919</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e κάθησαι 2ª sing. pres. ind., καθήατο 3ª pl. ép. impf., de κάθημαι.</p></section></article>\n<article id=\"entry-dgp-20920\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθηγεμών, όνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 135 na letra κ · nº geral 20920</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 guia: καθ. τῆς ἀρετῆς plut. guia da virtude 2 mestre. 〈καθηγέομαι〉</p></section></article>\n<article id=\"entry-dgp-20921\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθηγέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 136 na letra κ · nº geral 20921</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 guiar; indicar o caminho; servir de guia a alguém, dat. 2 ensinar; explicar algo, ac., a alguém, dat. 3 ser preceptor de alguém, gen. 4 tomar a iniciativa ou a direção de, gen. 5 ser o promotor de; propor 6 dar início; começar, gen. ou part.</p></section></article>\n<article id=\"entry-dgp-20922\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθηγητής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 137 na letra κ · nº geral 20922</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 guia; condutor 2 mestre; preceptor; professor. 〈καθηγέομαι〉</p></section></article>\n<article id=\"entry-dgp-20923\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθηδυπαθέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 138 na letra κ · nº geral 20923</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dissipar a fortuna na volúpia e nos prazeres 2 desperdiçar (tempo).</p></section></article>\n<article id=\"entry-dgp-20924\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθῆκα</h1><div class=\"entry-meta\"><span>DGP · ordem 139 na letra κ · nº geral 20924</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. de καθίημι.</p></section></article>\n<article id=\"entry-dgp-20925\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κἄθηκα, κἄθηκας</h1><div class=\"entry-meta\"><span>DGP · ordem 140 na letra κ · nº geral 20925</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase poét. de καὶ ἔθηκα, καὶ ἔθηκας.</p></section></article>\n<article id=\"entry-dgp-20926\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθῆκον, οντος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 141 na letra κ · nº geral 20926</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. καθήκω.</p></section></article>\n<article id=\"entry-dgp-20927\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθηκόντως</h1><div class=\"entry-meta\"><span>DGP · ordem 142 na letra κ · nº geral 20927</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. como convém; de modo apropriado. 〈καθήκω〉</p></section></article>\n<article id=\"entry-dgp-20928\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθήκω,</h1><div class=\"entry-meta\"><span>DGP · ordem 143 na letra κ · nº geral 20928</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. κατήκω (impf. καθῆκον, fut. καθήξω) 1 (lugar) descer à liça, à arena 2 descer até; descer; atingir; chegar a, εἰς, ἐπί ou πρὸς e ac.: καθῆκεν εἰς ἡμᾶς ὁ λόγος ésqn. o discurso chegou a nós, i.e., chegou nossa vez de falar 3 (tempo) chegar: ἑορτῆς εἰς τὰς ἡμέρας ἐκείνας καθηκούσης plut. como a festa caía naquele dia 4 ser oportuno; ser apropriado, conforme a norma: τοῦ καθή­κον­τος χρόνου dem. na data apropriada, πλείω τοῦ κα­θήκοντος χρόνου sóf. mais do que o tempo normal, πρὸ τοῦ καθήκοντος χρόνου ésqn. antes do tempo prescrito, ταῖς καθηκούσαις ἡμέραις dem. nos dias normalmente estabelecidos, εἰς τὴν καθήκουσαν σύνοδον pol. à assembléia normal ou prescrita, ἐσθῆτες καθήκουσαι pol. roupas adequadas 5 impes. καθήκει convém; é apropriado; é oportuno, com dat. e inf.: ὡς καθήκει πάσῃ τῇ γῇ sept. segundo o costume de toda a terra, ὡς καθήκει sept. segundo a lei, πάντα ὅσα μοι καθήκει sept. tudo quanto me é necessário; poster. impf = pres. οὐ καθῆκεν αὐτὸν ζῆν n.t. ele não deve viver ♦ τὸ καθῆκον 6 o dever; o que convém ♦ τὰ καθήκοντα (jôn.) 7 a situação; o que se deve enfrentar: τὰ κατήκοντα πρήγματα her. ou τὰ κατήκοντα her. o estado atual dos negócios. 〈κατά, ἥκω〉</p></section></article>\n<article id=\"entry-dgp-20929\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθηλόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 144 na letra κ · nº geral 20929</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pregar algo, ac., em algo, πρός e ac. ou dat., ou περί e ac. 2 trespassar (com pregos).</p></section></article>\n<article id=\"entry-dgp-20930\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάθημαι,</h1><div class=\"entry-meta\"><span>DGP · ordem 145 na letra κ · nº geral 20930</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. κάτημαι (imper. 2ª sing. κάθησο, subj. καθῶμαι, opt. καθοίμην ou καθῄμην, inf. καθῆσθαι, part. καθήμενος; impf. ἐκαθήμην, ger. sem aum. na 2ª e 3ª do sing. καθῆσο, καθῆτο ou καθῆστο, e do plur. καθῆσθε e καθῆντο) 1 estar sentado; permanecer em ou sobre, ac. ou dat., ἐπί e gen. ou dat., ἐν e dat.: καθῆσθαι τήνδ’ ἕδραν καλὴν δοκεῖς eur. achas que estás bem neste banco, λεπαίαν δ’ ὀφρύην καθήμενος σκοπεῖ eur. permanecendo sobre o penhasco elevado observa, κάθ. θρόνῳ eur. ou ἐπὶ τοῦ θρόνου sept. estar sentado num trono, κάθ. θύρῃσι hom. ou κάθ. ἐπὶ ταῖσι θύραις artt. estar sentado à porta, καθήμενος ἐπὶ πέτρῃ hom. estar sentado sobre um rochedo, κάθ. ἐπὶ ἀκτῆς hom. estar sentado à margem, na praia, κάθ. ἐπὶ τῶν ἵππων xen. estar a cavalo, κάθ. ἐπὶ δίφρου plat. estar sentado num banco (de carro), κάτ. ἐν θρόνῳ her. estar sentado num assento, οἱ καθήμενοι tuc. os que têm assento em (juízes, membros de assembléia, os espectadores, os mendigos) 2 permanecer no mesmo lugar 3 ficar tranqüilo, imóvel, inerte: ἐπὶ δύο ἔτεα ἐν πένθεϊ μεγάλῳ κατῆστο her. por dois anos permaneceu em grande luto, ἔχων δύναμιν τοσαύτην κάτησαι her. tendo tão grande poder permaneces inoperante, προϊέναι καὶ μὴ καθῆσθαι tuc. avançar e não ficar inativo 4 ser sedentário; levar uma vida sedentária; desenvolver uma atividade sedentária: εἰσὶ δὲ οἱ ἐπ’ αὐτῷ τούτῳ κατέαται her. são pessoas acostumadas a este (trabalho) 5 estar estabelecido; residir: καθ. ἐν ∆έλφοισιν her. residir em Delfos 6 (objeto) estar colocado 7 (lugar) estar situado.</p></section></article>\n<article id=\"entry-dgp-20931\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθημερινός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 146 na letra κ · nº geral 20931</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">diário; cotidiano. 〈κατά, ἡμέρα〉</p></section></article>\n<article id=\"entry-dgp-20932\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθημέριος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 147 na letra κ · nº geral 20932</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">deste dia; de hoje; de cada dia. 〈κατά, ἡμέρα〉</p></section></article>\n<article id=\"entry-dgp-20933\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθῆραι</h1><div class=\"entry-meta\"><span>DGP · ordem 148 na letra κ · nº geral 20933</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor. de καθαίρω.</p></section></article>\n<article id=\"entry-dgp-20934\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθῇρημαι</h1><div class=\"entry-meta\"><span>DGP · ordem 149 na letra κ · nº geral 20934</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perf. pas. de καθαιρέω.</p></section></article>\n<article id=\"entry-dgp-20935\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθῆσο, καθῆστο, καθῆτο</h1><div class=\"entry-meta\"><span>DGP · ordem 150 na letra κ · nº geral 20935</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. κάθημαι.</p></section></article>\n<article id=\"entry-dgp-20936\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθῆψα</h1><div class=\"entry-meta\"><span>DGP · ordem 151 na letra κ · nº geral 20936</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. de καθάπτω.</p></section></article>\n<article id=\"entry-dgp-20937\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθιδρύω</h1><div class=\"entry-meta\"><span>DGP · ordem 152 na letra κ · nº geral 20937</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer sentar 2 fazer residir; estabelecer; fixar ♦ méd. 3 pôr; colocar 4 erigir; fundar 5 consagrar; dedicar.</p></section></article>\n<article id=\"entry-dgp-20938\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθίει</h1><div class=\"entry-meta\"><span>DGP · ordem 153 na letra κ · nº geral 20938</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. impf. de καθίημι.</p></section></article>\n<article id=\"entry-dgp-20939\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθιέρευσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 154 na letra κ · nº geral 20939</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de oferecer em sacrifício; consagração. 〈καθιερεύω〉</p></section></article>\n<article id=\"entry-dgp-20940\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθιερεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 155 na letra κ · nº geral 20940</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">oferecer em sacrifício; consagrar.</p></section></article>\n<article id=\"entry-dgp-20941\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθιερόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 156 na letra κ · nº geral 20941</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">consagrar; dedicar algo, ac., a alguém, dat.: ὡς ἑαυτοὺς ὑπὲρ τῆς πατρίδος τῷ δαίμονι καθιεροῦντες plut. que se consagravam à divindade em benefício da pátria.</p></section></article>\n<article id=\"entry-dgp-20942\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθιέρωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 157 na letra κ · nº geral 20942</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">consagração; dedicação. 〈καθιερόω〉</p></section></article>\n<article id=\"entry-dgp-20943\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθιζάνω</h1><div class=\"entry-meta\"><span>DGP · ordem 158 na letra κ · nº geral 20943</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf. ép. καθίζανον) 1 sentar-se 2 (animal) repousar.</p></section></article>\n<article id=\"entry-dgp-20944\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθίζον</h1><div class=\"entry-meta\"><span>DGP · ordem 159 na letra κ · nº geral 20944</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impf. ép. de καθίζω.</p></section></article>\n<article id=\"entry-dgp-20945\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 160 na letra κ · nº geral 20945</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. καθίσω, át. καθιῶ, aor. ἐκάθισα, át. καθῖσα, perf. κεκάθικα) 1 fazer sentar: σ’ ἐπ’ ἐμοῖσιν ἐγὼ γού­νεσσι κατίσσας hom. fazendo-te sentar sobre meus joelhos, ἐπαγγελλόμεθα εἰς τὸν θρόνον τὸν βασίλειον καθιεῖν αὐτόν xen. prometemos que o faríamos sentar no trono real 2 estabelecer; instituir; convocar; empossar: τὴν βουλὴν ἐπίσκοπον ἐκάθισε plut. estabeleceu o senado como vigia, καθ. ἀγοράς hom. convocar a assembléia, δικαστήρια καθίσαντας plat. tendo empossado o tribunal, δικαστήν… καθιζέτω τῶν γειτόνων τὸν ἐγγύτατα plat. que estabeleça como juiz o mais próximo dos vizinhos 3 colocar; dispor: καθίσας τὸν στρατόν tuc. tendo feito o exército acampar, καθ. φύλακας xen. postar guardas, καθίσαντες ἐνέδραν plut. tendo armado uma emboscada 4 colocar numa dada condição, em situação de, com part. ou inf.: τινὰ κλαίοντα καθίζειν plat. ou κλάειν τινά xen. fazer alguém chorar 5 sentar-se; sentar em ou sobre, ac., ἐν e dat., ἐπί e ac. ou gen.: καθίζει τρίποδα eur. senta no tripé καθίζουσιν ἐπὶ τὸν βωμὸν ἱκέται tuc. suplicantes sentam ao pé do altar, ἐπὶ τῶν ἐργαστηρίων καθίζων isócr. sentando em prostíbulos, ἐκάθισα ἐπὶ τοῦ θρόνου sept. sentei-me no trono, εἰ μετ’ ἀθανάτοισι καθίζοις hom. se pudesses sentar-te entre os imortais 6 (magistrados) ter assento 7 (exército) acampar 8 (navio) encalhar 9 tard., bíbl. permanecer; residir ♦ méd. (fut. καθιζήσομαι) 10 sentar-se.</p></section></article>\n<article id=\"entry-dgp-20946\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθίημι,</h1><div class=\"entry-meta\"><span>DGP · ordem 161 na letra κ · nº geral 20946</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. κατίημι (fut. καθήσω, aor. καθῆκα, perf. καθεῖκα; méd. καθίεμαι, fut. καθήσομαι, aor. καθείμην, perf. καθείμαι) ativa 1 fazer descer; fazer cair; lançar do alto; jogar 2 deixar cair; soltar 3 fazer descer à arena; lançar na competição 4 lançar; produzir; trazer a público 5 fazer descer 6 descer ou lançar-se; precipitar-se (ἑαυτόν) 7 fazer voltar à pátria média 8 descer em; transportar-se para, εἰς e ac. 1 καθ. κεραυνὸν χαμᾶζε hom. lançar o raio sobre a terra, καθ. ὑψόθεν ἐέρσας hom. fazer cair do alto o orvalho, οἶνον λαυκανίης καθέηκα hom. deixei descer vinho pela goela, ἄγκυραν καθῆσαν her. jogaram âncoras, καθῆκε τὸ σκῶμμα ἐπί τινα luc. fez uma caçoada de alguém, ζωοὺς δ’ ἐν δίνῃσι καθίετε… ἵππους hom. os cavalos, vós os lançais vivos nos vórtices, ἐς ταύτην κοντὸν κατιεῖσι her. nesse (lago) lançam um remo, οὐ δραπέτην τὸν κλῆρον ἐς μέσον καθιείς sóf. não tendo lançado no meio um tento fujão, καθ. ὅπλα εἰς ἅλα eur. jogar as armas no mar, καθῆκ’ ἐμαυτὸν εἰς ἅλα eur. joguei-me no mar 2 καθ. τὰς κώπας tuc. soltar os remos, καθεῖσα πρὸς γαῖαν γόνυ eur. tendo colocado o joelho no chão, καθειμένος τὸν πώγωνα plut. tendo deixado crescer a barba, καθ. πώγωνα artt. deixar crescer a barba (colocar postiça), καθῆκε τὰ σκέλη ἐπὶ τὴν γῆν plat. (da cama) desceu as pernas até o chão, εἰς προσβολὴν καθέντας [δόρατα] xen. tendo baixado as lanças para o golpe (as lanças em riste), καθ. τὰ δίκτυα artt. baixar ou jogar as redes, τὰ οὔατα καθιᾶσι artt. (as ovelhas) baixam as orelhas, καθεῖσαν δέλεαρ ἡδύ μοι φρενῶν eur. fizeram descer (introduziram) uma doce sedução em meu coração, οἵαν πρόφασιν καθῆκεν ar. que pretexto propõe 3 ἅρματα μὲν ἑπτὰ καθῆκα tuc. lancei na corrida sete carros, ζεύγη καθ. isócr. lançar parelhas de animais 4 πρώτην διδασκαλίαν καθέντος plut. quando lançou a primeira didascália 5 καθ. τείχη tuc. estender muralhas (até o mar) 6 καθ. ἀφ’ ὑψηλῶν xen. descer de lugar elevado, καθ. εἰς γόνυ plut. cair de joelhos, καθ. εἰς ἀγῶνα plut. descer à liça 7 καθ. φυγάδας xen. chamar de volta os exilados 8 κατίετο ἐς πᾶσαν τὴν Ἑλλάδα her. descia contra toda a Grécia, i.e., atingia toda a Grécia.</p></section></article>\n<article id=\"entry-dgp-20947\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθίκεο</h1><div class=\"entry-meta\"><span>DGP · ordem 162 na letra κ · nº geral 20947</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. aor.2 poét., καθικέσθαι inf. aor.2 de κα­θικνέομαι.</p></section></article>\n<article id=\"entry-dgp-20948\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθικετεύω,</h1><div class=\"entry-meta\"><span>DGP · ordem 163 na letra κ · nº geral 20948</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. κατικετεύω at. e méd. 1 suplicar; dirigir súplicas a alguém, dat. 2 suplicar a alguém, gen. ou ac., algo, ac. ou inf.</p></section></article>\n<article id=\"entry-dgp-20949\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθικνέομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 164 na letra κ · nº geral 20949</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. καθίξομαι, aor.2 καθικόμην) 1 atingir; golpear; ferir, ac. ou gen.: καθ. κάρα sóf. golpear a cabeça, με μάλιστα καθίκετο πένθος ἄλαστον hom. atingiu-me um sofrimento insuportável 2 atingir; tocar, ac. ou gen.: τῆς ψυχῆς καθ. plat. atingir o ânimo, καθ. θυμόν hom. tocar o coração 3 chegar a; obter, gen.</p></section></article>\n<article id=\"entry-dgp-20950\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθιμάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 165 na letra κ · nº geral 20950</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fazer descer com uma corda; fazer descer.</p></section></article>\n<article id=\"entry-dgp-20951\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθίμησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 166 na letra κ · nº geral 20951</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de descer com uma corda; descida com uma corda. 〈καθιμάω〉</p></section></article>\n<article id=\"entry-dgp-20952\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθιξῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 167 na letra κ · nº geral 20952</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. dór. de καθίζω.</p></section></article>\n<article id=\"entry-dgp-20953\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθιππάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 168 na letra κ · nº geral 20953</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cavalgar ♦ méd. (fut. καθιππάσομαι) 2 devastar com incursões de cavalaria 3 pisotear: παλαιοὺς νόμους καθ. ésql. pisotear antigas leis.</p></section></article>\n<article id=\"entry-dgp-20954\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάθισα</h1><div class=\"entry-meta\"><span>DGP · ordem 169 na letra κ · nº geral 20954</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. ép. de καθίζω.</p></section></article>\n<article id=\"entry-dgp-20955\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάθισις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 170 na letra κ · nº geral 20955</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de sentar 2 ação de estabelecer. 〈καθίζω〉</p></section></article>\n<article id=\"entry-dgp-20956\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθίσσας</h1><div class=\"entry-meta\"><span>DGP · ordem 171 na letra κ · nº geral 20956</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor. ép. de καθίζω.</p></section></article>\n<article id=\"entry-dgp-20957\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθίστα</h1><div class=\"entry-meta\"><span>DGP · ordem 172 na letra κ · nº geral 20957</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. imper. pres. at. de καθίστημι.</p></section></article>\n<article id=\"entry-dgp-20958\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθιστάνω</h1><div class=\"entry-meta\"><span>DGP · ordem 173 na letra κ · nº geral 20958</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf. καθίστανον) = καθίστημι.</p></section></article>\n<article id=\"entry-dgp-20959\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάθισον</h1><div class=\"entry-meta\"><span>DGP · ordem 174 na letra κ · nº geral 20959</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. imper. aor. de καθίζω.</p></section></article>\n<article id=\"entry-dgp-20960\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθίστημι,</h1><div class=\"entry-meta\"><span>DGP · ordem 175 na letra κ · nº geral 20960</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. κατίστημι (tr. no impf. καθίστην, fut. καταστήσω, aor. κατέστησα, perf. καθέστακα,; intr. aor.2 κατέστην, perf. καθέστηκα, m.-q.-perf. καθειστήκειν, fut. ant. καθεστήξω; méd. καθίσταμαι, fut. καταστήσομαι, aor. καθεστησάμην) ativa 1 colocar diante; apresentar 2 deter; parar 3 transportar; conduzir para colocar, εἰς e ac.; restabelecer 4 dispor; estabelecer; colocar alguém, ac., em determinada situação, ac. ou ἐπί, εἰς e ac., ἐν e dat., ou or. inf. ou adj. ou part. 5 intr. transportar-se para algum lugar, ἐς e ac.; ir para junto de alguém, ἐπί e ac.; (tropas) ser colocado, disposto; estabelecer-se; constituir-se 6 retomar seu lugar; fixar-se; ficar tranqüilo; acalmar-se média 7 estabelecer 8 colocar-se em determinada situação 1 κρητῆρα… κάθιστα hom. apresenta uma cratera 2 νῆα κατάστησον hom. pára tua nau, κατ. πόδα eur. deter o passo, parar 3 Πύλονδε καταστῆσαι hom. transportar a Pilo, ἐς ∆ῖον κατ. tuc. conduzir a Dion, ἐς φῶς κατ. βίον eur. conduzir a vida à luz, πάλιν αὐτὸν καταστήσειν ἐς τὸ τεῖχος σῶν καὶ ὑγιᾶ tuc. (dizendo) que o teria reconduzido à muralha são e salvo, μέχρι ἂν καταστήσῃ τοὺς Ἕλληνας εἰς Ἰωνίαν πάλιν xen. até que reconduzisse os gregos à Jônia, κατεστήσαντο εὐδαιμονίαν isócr. restabeleceram a felicidade 4 κατ. τινὰ ἐπὶ τὰς ἀρχάς isócr. levar alguém ao poder, κατ. τινὰ εἰς ἀσφάλειαν isócr. colocar alguém em segurança, κατ. ἑαυτὸν εἰς κρίσιν tuc. pôr-se à disposição para um processo, κατ. ἐς ἔλεγχόν τινα her. submeter alguém à comprovação, κατ. τινὰ ἐς ἀπορίαν tuc. colocar alguém em dificuldade, κατ. τινὰ εἰς ἀνάγκην lís. expor alguém à necessidade, κατ. ἄρχοντα xen. instituir um magistrado, κατ. τύραννον εἶναί τινα her. instituir alguém como rei, ἐντιμότερόν τινα κατ. xen. tornar alguém alvo de maiores honrarias, κατ. τι φανερόν tuc. tornar algo evidente, κατ. τινὰ φεύγειν tuc. levar alguém a fugir, κατ. τινὰ ἐν ἀγῶνι καὶ κινδύνῳ antíf. pôr alguém na situação de confronto e de perigo, τὴν πόλιν ἐν πολέμῳ κατ. plat. levar a cidade à guerra 5 κατ. ἐς ὄψιν her. vir à presença de alguém, κατ. ἐς Ῥήγιον tuc. estabelecer-se em Régio, καταστὰς ἐπὶ τὸ πλῆθος ἔλεγε tuc. tendo vindo diante do povo dizia, ὅταν καταστῶσιν οἱ ἄρχοντες plat. quando os arcontes assumirem o cargo, καταστῆναι εἰς ἔχθραν τινί isócr. entrar em rivalidade com alguém, rivalizar com alguém, φύλαξ δέ μου πιστὴ κατέστης sóf. tu te puseste como minha guardiã fiel, ὅσου κατέστη plut. tanto quanto estabelecido, μαίνεσθαι καὶ ἔξω τοῦ καθεστηκότος εἶναι luc. estar demente e fora de si, καθεστῶτες νόμοι sóf. as leis estabelecidas, κατεστεὼς κόσμος her. a ordem estabelecida, τὰ καθεστῶτα sóf. o estado das coisas 6 λέξον καταστάς her. pára e fala, i.e., com calma fala, ἐπείτε δὲ κατέστη ὁ θόρυβος her. quando o tumulto baixou 7 τοῦτο βουλευτήριον φρούρημα γῆς καθίσταμαι ésql. ponho este tribunal como baluarte desta terra, ἐπειδὰν δὲ καταστήσησθε τοὺς ἄρχοντος ὅσους δεῖ xen. quando tiverdes nomeado arcontes quantos forem necessários, τύραννον καταστησάμενοι παρὰ σφίσι αὐτοῖσι her. tendo estabelecido para si mesmos um tirano, καθίστατο τὰ περὶ τὴν Μυτιλήνην ᾗ αὐτῷ ἐδόκει tuc. estabeleceu o relativo a Mitilene como lhe pareceu bem 8 ἄπαρνος οὐδενὸς καθίστατο sóf. punha-se como alguém que nada negava.</p></section></article>\n<article id=\"entry-dgp-20961\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθιῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 176 na letra κ · nº geral 20961</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. át. de καθίζω.</p></section></article>\n<article id=\"entry-dgp-20962\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθό</h1><div class=\"entry-meta\"><span>DGP · ordem 177 na letra κ · nº geral 20962</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">καθ’ ὅ 1 segundo; como; relativamente a; na qualidade de 2 de tal modo que. 〈κατά, ὅ〉</p></section></article>\n<article id=\"entry-dgp-20963\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθοδηγέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 178 na letra κ · nº geral 20963</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">guiar; conduzir. 〈κατά, ὁδηγός〉</p></section></article>\n<article id=\"entry-dgp-20964\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάθοδος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 179 na letra κ · nº geral 20964</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 caminho para baixo; descida 2 ação de descer; descida 3 retorno; volta do exílio 4 retorno periódico; ciclo; período. 〈κατά, ὁδός〉</p></section></article>\n<article id=\"entry-dgp-20965\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθοίμην</h1><div class=\"entry-meta\"><span>DGP · ordem 180 na letra κ · nº geral 20965</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">opt. de κάθημαι.</p></section></article>\n<article id=\"entry-dgp-20966\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθολικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 181 na letra κ · nº geral 20966</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 geral; universal: καθ. ἱστορία pol. história universal, καθολικώτεροι λόγοι sept. = καθόλικοι λόγοι herm. lugares comuns, ἡ καθολικὴ ἐκκλησία clem. a Igreja Católica, a Igreja universal ♦ ὁ καθολικός 2 crist. responsável geral (do mosteiro) ♦ τὸ κατολικόν 3 descrição geral. 〈κατά, ὅλος〉</p></section></article>\n<article id=\"entry-dgp-20967\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθόλου</h1><div class=\"entry-meta\"><span>DGP · ordem 182 na letra κ · nº geral 20967</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 em geral; em conjunto: καθ. εἰπεῖν dizer, falar em geral, ἡ τῶν καθ. πραγμάτων pol. a sistematização dos acontecimentos em geral, história universal, καθ. τὰς πράξεις γράφειν pol. escrever os fatos (a história) em geral 2 completamente; inteiramente; no total; absolutamente: καθ. τὸ καταλειφθέν dem. no total o que resta, οὐ καθ. de modo algum ♦ τὸ καθόλου 3 de modo geral; geralmente 4 Filos. o geral; o ideal ♦ τὰ καθόλου 5 a verdade ou afirmações universais. 〈κατά, ὅλου〉</p></section></article>\n<article id=\"entry-dgp-20968\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθομιλέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 183 na letra κ · nº geral 20968</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 conciliar; tornar favorável alguém ou algo, ac.: καθ. τοὺς καιρούς at. tornar favoráveis as circunstâncias, i.e., acomodar-se às circunstâncias 2 granjear favor de, dat.: καθ. τῷ πλήθει diod. granjear o favor do povo 3 tard. manter relações; conversar com, dat. ♦ pas. 4 ser habitual, comum, proverbial: ἡ καθωμιλημένη δόξα pol. a opinião comum.</p></section></article>\n<article id=\"entry-dgp-20969\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθομολογέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 184 na letra κ · nº geral 20969</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 concordar 2 prometer algo 3 dar em casamento alguém, ac., a alguém, dat. 4 prometer em pagamento ♦ méd. (perf. καθωμολόγημαι) 5 dar em casamento.</p></section></article>\n<article id=\"entry-dgp-20970\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθοπλίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 185 na letra κ · nº geral 20970</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. καθώπλισα) 1 armar; equipar 2 triunfar; vencer ♦ méd. 3 armar-se.</p></section></article>\n<article id=\"entry-dgp-20971\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθόπλισις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 186 na letra κ · nº geral 20971</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de armar 2 armamento. 〈καθοπλίζω〉</p></section></article>\n<article id=\"entry-dgp-20972\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθοράω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 187 na letra κ · nº geral 20972</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">at. e méd. (fut. κατόψομαι, aor.2 κατεῖδον, perf. καθέωρακα; pas. aor. καθώφθην, perf. καθῶμμαι) 1 olhar do alto ou até ou para baixo, ἐπί e gen. 2 ver; observar; percorrer com o olhar; contemplar; examinar; perceber 3 considerar.</p></section></article>\n<article id=\"entry-dgp-20973\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθορμίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 188 na letra κ · nº geral 20973</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. καθορμίσω, át. καθορμιῶ, aor. καθώρ­μισα) 1 fazer atracar ou ancorar: καθ. στόλον εἰς νεώριον plut. fazer atracar uma frota no porto, καθ. ἑαυτὸν εἰς ἡσυχίαν plut. chegar à paz, καθ. ἑαυτὸν ἐς πημονάς ésql. ancorar em um porto de desgraças ♦ méd. pas. (aor. καθωρμισάμην) 2 chegar a um porto; atracar; jogar âncora 3 ser atado ou suspenso a. 〈κατά, ὁρμίζω〉</p></section></article>\n<article id=\"entry-dgp-20974\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθοσιόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 189 na letra κ · nº geral 20974</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 oferecer em sacrifício; consagrar 2 santificar; purificar ♦ méd. 3 consagrar para si; dedicar. 〈κατά, ὁσιόω〉</p></section></article>\n<article id=\"entry-dgp-20975\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθόσον</h1><div class=\"entry-meta\"><span>DGP · ordem 190 na letra κ · nº geral 20975</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">καθ’ ὅσον adv. tanto quanto; assim como.</p></section></article>\n<article id=\"entry-dgp-20976\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθότι</h1><div class=\"entry-meta\"><span>DGP · ordem 191 na letra κ · nº geral 20976</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">καθ’ ὅ τι conj. 1 como; do modo como 2 conforme o que; como. 〈κατά, ὅτι〉</p></section></article>\n<article id=\"entry-dgp-20977\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάθου</h1><div class=\"entry-meta\"><span>DGP · ordem 192 na letra κ · nº geral 20977</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. imper. pres. poét. de κάθημαι, ou 2ª sing. imper. aor.2 méd. de καθίημι.</p></section></article>\n<article id=\"entry-dgp-20978\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθυβρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 193 na letra κ · nº geral 20978</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ultrajar; insultar; maltratar, ac., gen., dat. ou εἰς e ac.</p></section></article>\n<article id=\"entry-dgp-20979\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθυγραίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 194 na letra κ · nº geral 20979</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tornar totalmente úmido; liquefazer.</p></section></article>\n<article id=\"entry-dgp-20980\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάθυδρος</h1><div class=\"entry-meta\"><span>DGP · ordem 195 na letra κ · nº geral 20980</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cheio de água 2 abundante de águas. 〈κατά, ὕδωρ〉</p></section></article>\n<article id=\"entry-dgp-20981\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθυλακτέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 196 na letra κ · nº geral 20981</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">latir contra, gen.</p></section></article>\n<article id=\"entry-dgp-20982\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθυμνέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 197 na letra κ · nº geral 20982</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cantar; celebrar alguém 2 cantar em louvor de alguém, dat.</p></section></article>\n<article id=\"entry-dgp-20983\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθυπάρχω</h1><div class=\"entry-meta\"><span>DGP · ordem 198 na letra κ · nº geral 20983</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ὑπάρχω.</p></section></article>\n<article id=\"entry-dgp-20984\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθύπερθε</h1><div class=\"entry-meta\"><span>DGP · ordem 199 na letra κ · nº geral 20984</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e, diante de vogal, καθύπερθεν adv. 1 (lugar) do alto; do alto de, gen. 2 (lugar) no alto; acima: ἡ καθύπερθε Φρυγίη hom. a Frígia superior, ἡ χώρη ἡ καθ. her. a região mais para cima, ao norte, καθ. Χίοιο hom. ao norte de Quios, τὰ καθ. a região superior, a mais interior, τὰ καθ. τῆς λίμνης her. a região ao norte do lago 3 (lugar) acima de: καθ. τινὸς γενέσθαι her. ser superior a alguém ou algo, μόχθου καθ. superior à miséria, καθύπερθεν χερὶ πλούτῳ τε τῶν ἐχθρῶν sóf. superior aos inimigos em força e riqueza, καθ. ἤ her. acima de, gen. 4 (tempo) antes de, gen. 〈κατά, ὕπερθε〉</p></section></article>\n<article id=\"entry-dgp-20985\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθυπέρτατος,</h1><div class=\"entry-meta\"><span>DGP · ordem 200 na letra κ · nº geral 20985</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. κατυπέρτατος, α, ον superl. de κα­θυπέρτερος.</p></section></article>\n<article id=\"entry-dgp-20986\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθυπέρτερος,</h1><div class=\"entry-meta\"><span>DGP · ordem 201 na letra κ · nº geral 20986</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. κατυπέρτερος, α, ον mais elevado; superior a alguém, gen.: κατυπέρτεροι τῷ πολέμῳ her. vencedores na guerra. 〈κατά, ὑπέρ〉</p></section></article>\n<article id=\"entry-dgp-20987\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθυπισχνέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 202 na letra κ · nº geral 20987</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor.2 καθυπεσχόμην) prometer.</p></section></article>\n<article id=\"entry-dgp-20988\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθυπνόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 203 na letra κ · nº geral 20988</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">at. e méd. dormir profundamente.</p></section></article>\n<article id=\"entry-dgp-20989\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθυποκρίνομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 204 na letra κ · nº geral 20989</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 agir como ator; enganar com arte cômica 2 fingir.</p></section></article>\n<article id=\"entry-dgp-20990\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθυστερέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 205 na letra κ · nº geral 20990</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ficar atrás; chegar atrasado ou depois de, gen.: θανάτου οὐ καθ. luc. não adiar a morte 2 atrasar para, dat., ac., duplo gen.: καθ. τῇ διώξει plut. estar atrasado para a perseguição 3 faltar; falhar, gen.</p></section></article>\n";
